const Q=[
{t:'priority',s:'yield',q:'Вы подъезжаете к нерегулируемому перекрёстку. Перед вами установлен знак «Уступить дорогу», а справа приближается автомобиль по пересекаемой дороге. Что необходимо определить в первую очередь?',a:['Имеется ли транспортное средство справа, независимо от знаков','Как действующий знак приоритета распределяет преимущество между направлениями','Кто из автомобилей первым достиг границы перекрёстка','Можно ли проехать первым, если вы не заставите автомобиль справа тормозить'],c:1,r:'При наличии знаков приоритета очередность сначала определяется ими. Правило помехи справа не подменяет требования знаков.',e:'Здесь ловушка в том, что автомобиль действительно находится справа. Но прежде чем применять правило справа, нужно установить значение знака приоритета.',m:'Слишком рано применяете помеху справа'},
{t:'priority',s:'yield',q:'Вы движетесь по второстепенной дороге и намерены повернуть направо. По главной дороге слева приближается автомобиль, который также поворачивает направо на вашу дорогу. Какой подход к решению задачи правильный?',a:['Считать, что при повороте направо вы всегда имеете преимущество','Сначала установить, пересекаются ли траектории, а затем применить требования знаков приоритета','Считать, что преимущество у автомобиля, который находится слева','Ориентироваться на то, кто раньше включил указатель поворота'],c:1,r:'Знак определяет приоритет, но фактическая обязанность уступить оценивается вместе с траекториями участников.',e:'Умная задача на приоритет требует не только увидеть знак, но и понять, возникает ли реальный конфликт траекторий.',m:'Определяете приоритет без проверки траекторий'},
{t:'priority',s:'yield',q:'На нерегулируемом перекрёстке равнозначных дорог автомобиль приближается справа. Вы намерены двигаться прямо, а он — повернуть налево. Кто должен уступить?',a:['Автомобиль справа, потому что при левом повороте всегда уступают движущемуся прямо','Вы, потому что на равнозначном перекрёстке сначала учитывается транспортное средство справа','Тот, кто позже въехал на перекрёсток','Оба могут начать движение одновременно, так как траектории различаются'],c:1,r:'На равнозначном нерегулируемом перекрёстке положение транспортного средства справа определяет исходную очередность, если иные правила её не изменяют.',e:'Фраза «при левом повороте уступают встречному» здесь не должна автоматически вытеснять правило, определяющее очередность на равнозначном перекрёстке.',m:'Смешиваете разные правила приоритета'},
{t:'priority',s:'yield',q:'Вы въезжаете на перекрёсток с круговым движением. Как наиболее надёжно определить, кому уступать?',a:['Всегда считать, что преимущество у транспортных средств на круге','Всегда считать, что преимущество у въезжающего справа','Оценить знаки приоритета и конкретную организацию движения перед въездом','Ориентироваться на то, кто движется по большей по радиусу полосе'],c:2,r:'На конкретном круговом перекрёстке порядок движения определяется установленной организацией и знаками, а не универсальной догадкой.',e:'Запоминание одного шаблона для всех круговых перекрёстков опасно. Сначала нужно читать конкретные знаки.',m:'Используете шаблон вместо анализа знаков'},
{t:'signals',s:'lane',q:'Вы поворачиваете налево на разрешающий сигнал светофора. Встречный автомобиль движется прямо и также имеет разрешающий сигнал. Как действовать?',a:['Начать поворот первым, если вы уже выехали к центру перекрёстка','Уступить встречному автомобилю, траектория которого пересекается с вашей','Продолжить одновременно, если встречный автомобиль находится дальше от центра','Ориентироваться на то, чей разрешающий сигнал включился раньше'],c:1,r:'Разрешающий сигнал не создаёт безусловного преимущества при конфликте с разрешённым встречным движением.',e:'Зелёный сигнал отвечает на вопрос «можно ли двигаться», но не всегда отвечает на вопрос «кто проедет первым».',m:'Считаете разрешающий сигнал безусловным преимуществом'},
{t:'signals',s:'lane',q:'Светофор работает в режиме жёлтого мигающего сигнала. Как правильно определить очередность проезда?',a:['Считать перекрёсток регулируемым и руководствоваться последним запомненным сигналом','Руководствоваться знаками приоритета, а при необходимости — правилами проезда нерегулируемых перекрёстков','Обязательно остановиться перед стоп-линией и продолжить только после полной остановки других участников','Предоставить преимущество всем транспортным средствам, движущимся прямо'],c:1,r:'Жёлтый мигающий сигнал предупреждает об опасности, но не задаёт обычную очередность разрешающими и запрещающими фазами.',e:'Ключ — перестать воспринимать светофор как обычный работающий регулятор очередности и перейти к анализу знаков и правил нерегулируемого перекрёстка.',m:'Неправильно интерпретируете режим светофора'},
{t:'signals',s:'lane',q:'Регулировщик показывает сигнал, который не совпадает с работающим светофором. Как должен действовать водитель?',a:['Следовать светофору, если его сигнал разрешающий','Следовать указанию регулировщика','Сначала выполнить требование знака приоритета, затем регулировщика','Выбрать сигнал, позволяющий быстрее освободить перекрёсток'],c:1,r:'При непосредственном регулировании движения сигналы регулировщика являются определяющими.',e:'На экзамене проверяется знание иерархии регулирования, а не выбор наиболее удобного разрешающего сигнала.',m:'Не знаете иерархию средств регулирования'},
{t:'signals',s:'lane',q:'Включился разрешающий сигнал, но за перекрёстком образовался затор. Если вы въедете, автомобиль остановится внутри перекрёстка и перекроет поперечное движение. Как действовать?',a:['Въехать, потому что разрешающий сигнал даёт право занять перекрёсток','Въехать только до стоп-линии следующего направления','Не въезжать до появления возможности освободить перекрёсток','Въехать, если автомобиль впереди уже начал движение'],c:2,r:'Разрешающий сигнал не означает, что можно создать блокировку перекрёстка из-за затора за ним.',e:'Вопрос проверяет прогноз развития ситуации: важно не только право начать движение, но и возможность закончить проезд без помех другим направлениям.',m:'Игнорируете ситуацию за перекрёстком'},
{t:'signals',s:'pedestrian',q:'Загорелся разрешающий сигнал, но пешеход ещё завершает переход по вашей траектории. Что правильнее?',a:['Начать движение, оставив пешеходу достаточный боковой интервал','Дождаться, пока движение можно начать без создания опасности пешеходу','Начать движение медленно, если пешеход уже прошёл половину полосы','Подать короткий звуковой сигнал и продолжить движение'],c:1,r:'Разрешающий сигнал не отменяет обязанности учитывать участника, который уже находится на конфликтующей траектории.',e:'Разница между «движение разрешено» и «можно безопасно начать прямо сейчас» — одна из ключевых экзаменационных ловушек.',m:'Воспринимаете зелёный сигнал как безусловную команду ехать'},
{t:'signs',s:'yield',q:'На знакомом участке временная организация движения отличается от привычной. Какой подход верный?',a:['Продолжить по прежней схеме, если временный знак установлен недавно','Руководствоваться актуальной организацией движения, даже если она отличается от привычного маршрута','Следовать постоянной разметке, если она визуально лучше заметна временных указаний','Ориентироваться на навигатор, если его карта обновлена в этот день'],c:1,r:'Водитель должен учитывать действующие средства организации движения в текущей ситуации, а не прежнюю схему дороги.',e:'Знакомство с участком часто провоцирует движение «по памяти». На экзамене важна актуальная дорожная обстановка.',m:'Игнорируете временную организацию движения'},
{t:'signs',s:'lane',q:'Навигатор предлагает повернуть направо, но действующий дорожный знак запрещает этот манёвр. Как действовать?',a:['Выполнить поворот, если навигатор показывает официальную карту','Выполнить поворот, если он не создаст помех другим участникам','Руководствоваться дорожным знаком и перестроить маршрут','Остановиться перед поворотом и проверить маршрут повторно'],c:2,r:'Навигационное приложение не заменяет требования действующих средств организации дорожного движения.',e:'Даже технически безопасный манёвр остаётся недопустимым, если он запрещён действующим знаком.',m:'Подменяете требования дороги навигационной подсказкой'},
{t:'signs',s:'lane',q:'Из вашей полосы знак разрешает движение прямо и направо, но фактический поворот направо потребует пересечения действующей сплошной линии разметки. Как оценить ситуацию?',a:['Знак направления разрешает пересечение разметки для выполнения указанного манёвра','Манёвр допустим только при отсутствии транспортных средств справа','Необходимо одновременно учитывать требования знака и разметки; разрешённое направление не отменяет иное ограничение','Разметка имеет значение только при перестроении, но не при повороте'],c:2,r:'Средства организации движения должны оцениваться совместно; одно разрешение не отменяет другого действующего ограничения.',e:'Правдоподобная ошибка — принять знак разрешённого направления за «разрешение на всё необходимое для поворота».',m:'Не объединяете несколько условий задачи'},
{t:'signs',s:'yield',q:'Перед перекрёстком установлен знак приоритета, однако его действие кажется вам неочевидным из-за сложной геометрии дороги. Как лучше решать задачу?',a:['Сначала определить, какая дорога визуально шире','Сначала установить направление главной и второстепенной дороги по знакам и табличкам, затем сопоставить траектории','Применить правило помехи справа ко всем участникам и проверить, не возникает ли противоречия','Ориентироваться на расположение автомобилей относительно центра перекрёстка'],c:1,r:'Сложная геометрия не отменяет значения знаков; сначала нужно правильно интерпретировать схему приоритета.',e:'Такие вопросы требуют отделить форму перекрёстка от правил, которыми на нём задана очередность.',m:'Ориентируетесь на геометрию вместо схемы приоритета'},
{t:'pedestrians',s:'pedestrian',q:'При повороте направо пешеход уже движется через проезжую часть по траектории, которую займёт ваш автомобиль. Как действовать?',a:['Продолжить поворот, если траектория пешехода пока не достигла вашей полосы','Снизить скорость и продолжить, если пешеход видит автомобиль','Не создавать опасность и предоставить пешеходу возможность безопасно закончить движение по конфликтующей траектории','Остановиться только в том случае, если пешеход находится непосредственно перед автомобилем'],c:2,r:'При повороте нужно учитывать конфликт траекторий с пешеходами и не вынуждать их изменять безопасное движение из-за вашего манёвра.',e:'Экзаменационный смысл не в расстоянии «прямо сейчас», а в том, пересекутся ли траектории в ближайший момент.',m:'Оцениваете только текущее положение пешехода'},
{t:'pedestrians',s:'pedestrian',q:'Пешеход стоит у края проезжей части возле перехода и смотрит в сторону движения. Какой вывод наиболее обоснован?',a:['Пока он не ступил на проезжую часть, его поведение не должно влиять на режим движения','Следует учитывать вероятность начала перехода и заранее иметь запас для безопасной реакции','Достаточно перенести ногу на педаль тормоза, не меняя оценки скорости и дистанции','Следует остановиться в любом случае независимо от дистанции и других условий'],c:1,r:'Безопасное управление строится на прогнозе возможного развития ситуации, а не только на реакции после возникновения конфликта.',e:'Правильный вариант не утверждает, что пешеход обязательно начнёт переход. Он требует учитывать такую вероятность.',m:'Реагируете постфактум вместо прогнозирования'},
{t:'pedestrians',s:'pedestrian',q:'Перед пешеходным переходом обзор справа закрыт остановившимся фургоном. Что должно изменить ваше решение?',a:['Ничего, пока из-за фургона физически не появился пешеход','Необходимо учитывать скрытую зону и выбрать режим движения с запасом на возможное появление пешехода','Можно ориентироваться на отсутствие движения самого фургона','Достаточно сместиться левее в своей полосе, сохраняя скорость'],c:1,r:'Ограниченная обзорность повышает неопределённость и требует заранее учитывать скрытую опасность.',e:'Сложность вопроса в том, что опасность не видна. Нужно реагировать на условие ограниченной обзорности, а не ждать появления пешехода.',m:'Не учитываете скрытую опасность'},
{t:'pedestrians',s:'pedestrian',q:'Автомобиль в соседней полосе заметно замедляется перед нерегулируемым пешеходным переходом, хотя вам пешеход не виден. Как лучше интерпретировать ситуацию?',a:['Считать, что водитель собирается перестроиться после перехода','Учитывать, что перед ним может находиться пешеход, скрытый от вашего обзора','Продолжать с прежней скоростью, пока пешеход не появится в вашей полосе','Опережать замедлившийся автомобиль можно, если ваша полоса свободна'],c:1,r:'Поведение другого автомобиля может быть косвенным признаком опасности, которую вы пока не видите.',e:'Высококачественный экзаменационный вопрос проверяет способность читать не только объекты, но и действия других участников.',m:'Не распознаёте косвенные признаки опасности'},
{t:'manoeuvres',s:'lane',q:'Вы собираетесь перестроиться в соседнюю полосу, где автомобиль движется без изменения направления. Какой принцип определяет ваши действия?',a:['После включения указателя поворота водитель в соседней полосе обязан дать место','Перестраивающийся водитель должен убедиться, что манёвр не вынудит другого участника резко изменять скорость или направление','Преимущество зависит от того, чей автомобиль находится впереди хотя бы на половину корпуса','Если скорость вашего автомобиля выше, перестроение можно закончить первым'],c:1,r:'Указатель поворота предупреждает о намерении, но не создаёт преимущества при перестроении.',e:'Варианты построены вокруг типичных ошибочных «прав» на перестроение — по поворотнику, положению корпуса или скорости.',m:'Считаете указатель поворота источником преимущества'},
{t:'manoeuvres',s:'lane',q:'Вы включили указатель поворота заранее. Автомобиль в соседней полосе находится чуть позади, но быстро сокращает дистанцию. Что необходимо учитывать?',a:['Только текущее положение автомобиля относительно вашего заднего бампера','Только то, что указатель поворота был включён раньше начала сближения','Скорость сближения и возможность завершить перестроение без создания помехи','Достаточно убедиться, что автомобиль ещё не вошёл в вашу слепую зону'],c:2,r:'Оценка перестроения должна учитывать динамику: положение автомобиля через секунду может быть важнее его положения сейчас.',e:'Это вопрос на прогноз, а не на «фотографию» дорожной ситуации.',m:'Не учитываете скорость сближения'},
{t:'manoeuvres',s:'lane',q:'Перед боковым перемещением вы посмотрели в наружное зеркало и не увидели автомобилей. Почему этого может быть недостаточно?',a:['Зеркало не показывает точную скорость соседнего автомобиля','В зоне, не контролируемой зеркалом, может находиться другой участник','Перед перестроением нужно смотреть только во внутреннее зеркало','Наружное зеркало используется только для контроля дистанции сзади'],c:1,r:'Перед боковым манёвром необходимо учитывать участки пространства, которые не полностью контролируются зеркалами.',e:'Правильный ответ не отменяет использование зеркал — он показывает ограничение одного источника обзора.',m:'Пропускаете контроль слепой зоны'},
{t:'manoeuvres',s:'lane',q:'Вы пропустили нужный съезд и уже находитесь в полосе, из которой повернуть нельзя без резкого перестроения. Как действовать?',a:['Выполнить перестроение, если включить указатель заранее и снизить скорость','Остановиться в своей полосе и дождаться безопасного окна','Продолжить движение и перестроить маршрут на следующем безопасном участке','Сместиться к границе полосы и дождаться, пока соседние автомобили вас пропустят'],c:2,r:'Ошибка маршрута не даёт преимущества и не оправдывает создание опасной ситуации.',e:'Правильный вариант принимает потерю времени как меньший риск по сравнению с внезапным исправлением маршрута.',m:'Исправляете маршрут рискованным манёвром'},
{t:'manoeuvres',s:'lane',q:'Манёвр формально не запрещён, но обзор встречной полосы частично закрыт крупным транспортным средством. Какой вывод верный?',a:['Если прямого запрета нет, манёвр разрешён и может быть начат медленно','Манёвр можно начать, если первый участок траектории свободен','Отсутствие запрета не заменяет обязанности убедиться в безопасности при имеющейся обзорности','Достаточно подать звуковой сигнал перед началом манёвра'],c:2,r:'«Не запрещено» и «безопасно выполнить сейчас» — разные проверки.',e:'Одна из самых полезных экзаменационных ловушек: формальная разрешённость действия не отменяет требования безопасности.',m:'Путаете разрешённость и безопасность манёвра'},
{t:'stopping',s:'yield',q:'Вы нашли свободное место для остановки неподалёку от перекрёстка. Что необходимо проверить прежде всего?',a:['Достаточно ли места, чтобы автомобиль полностью поместился у края дороги','Действующие ограничения, расстояние до элементов дороги, обзорность и влияние на других участников','Есть ли рядом другие припаркованные автомобили, подтверждающие допустимость места','Можно ли быстро продолжить движение после посадки пассажира'],c:1,r:'Свободное физическое место не означает автоматически разрешённое и безопасное место остановки.',e:'Правильный вариант объединяет правовую и безопасностную оценку; остальные опираются на удобство или поведение других водителей.',m:'Считаете свободное место автоматически разрешённым'},
{t:'stopping',s:'yield',q:'В месте, где вы сомневаетесь в разрешённости стоянки, уже находятся несколько автомобилей. Как это должно повлиять на решение?',a:['Если автомобилей несколько, можно считать место фактически разрешённым','Можно остановиться рядом, если не создаётся дополнительного сужения проезжей части','Наличие других автомобилей не заменяет самостоятельную проверку знаков, разметки и ограничений','Можно остановиться на короткое время, даже если длительная стоянка могла бы быть запрещена'],c:2,r:'Действия других водителей не являются нормативным основанием для вашего решения.',e:'Одна из частых реальных ошибок — использовать чужое нарушение как подтверждение собственного права.',m:'Копируете действия других водителей'},
{t:'stopping',s:'pedestrian',q:'Вы планируете остановиться сразу после поворота. Место свободно, но ваш автомобиль может ухудшить обзор пешеходного перехода для других водителей. Что важнее?',a:['Короткая продолжительность остановки позволяет считать риск допустимым','Если автомобиль полностью у края дороги, ухудшение обзора не имеет значения','Нужно учитывать ограничения и влияние остановленного автомобиля на обзор и безопасность других участников','Достаточно включить аварийную сигнализацию, чтобы предупредить других'],c:2,r:'При выборе места остановки оцениваются не только формальные границы места, но и безопасность и обзорность.',e:'Аварийная сигнализация не превращает небезопасную остановку в безопасную.',m:'Не оцениваете влияние остановки на обзорность'},
{t:'speed',s:'rain',q:'После начала сильного дождя ухудшилась видимость и сцепление с дорогой. Как следует изменить режим движения?',a:['Сохранить прежнюю скорость, если она ниже установленного ограничения','Снизить скорость и увеличить дистанцию с учётом ухудшившихся условий','Сохранить скорость, но увеличить только боковой интервал','Сократить дистанцию, чтобы лучше ориентироваться по автомобилю впереди'],c:1,r:'Ограничение задаёт верхний предел, а фактические условия могут требовать меньшей скорости и большего запаса расстояния.',e:'Правильное решение одновременно учитывает видимость, сцепление и запас времени на реакцию.',m:'Не адаптируете скорость и дистанцию к условиям'},
{t:'speed',s:'rain',q:'Разрешённая скорость на участке выше той, при которой вы сможете остановиться в пределах хорошо просматриваемого пространства. Как выбирать скорость?',a:['Можно двигаться с максимально разрешённой скоростью, если тормоза исправны','Нужно выбрать меньшую скорость, соответствующую фактической видимости и возможности безопасно остановиться','Достаточно увеличить дистанцию до автомобиля впереди, не меняя скорость','Следует ориентироваться на среднюю скорость потока, если остальные автомобили не тормозят'],c:1,r:'Максимально разрешённая скорость — это предел, а не обязательное или автоматически безопасное значение.',e:'Вопрос проверяет различие между юридическим максимумом и безопасным режимом конкретной ситуации.',m:'Путаете разрешённую и безопасную скорость'},
{t:'speed',s:'rain',q:'Почему даже эффективная тормозная система не гарантирует короткую остановку, если препятствие обнаружено поздно?',a:['Потому что до начала торможения автомобиль проходит путь за время восприятия и реакции','Потому что тормозная система начинает действовать только после снижения скорости двигателем','Потому что тормозной путь определяется только массой автомобиля','Потому что при исправных тормозах основная часть остановочного пути всегда приходится на реакцию'],c:0,r:'Полный остановочный процесс включает путь, пройденный до фактического начала торможения.',e:'Правильный вариант не утверждает, что реакция всегда длиннее тормозного пути; он лишь учитывает её как отдельную обязательную составляющую.',m:'Недооцениваете путь за время реакции'},
{t:'speed',s:'lane',q:'Поток автомобилей движется заметно быстрее установленного ограничения. Как это влияет на допустимый выбор скорости?',a:['Можно поддерживать скорость потока, если резкое снижение скорости было бы неудобно другим','Допускается небольшое превышение, если дистанция достаточна','Установленное ограничение продолжает действовать независимо от скорости окружающего потока','Скорость потока становится ориентиром, если впереди нет камер контроля'],c:2,r:'Поведение окружающих участников не отменяет установленное ограничение скорости.',e:'Социальное давление потока — реальная причина ошибок, но не основание для изменения действующего ограничения.',m:'Ориентируетесь на поток вместо ограничения'},
{t:'speed',s:'lane',q:'Что наиболее важно при выборе дистанции до автомобиля впереди?',a:['Сохранить фиксированное расстояние, одинаковое при любой скорости','Иметь запас времени и пространства для реакции и торможения в текущих условиях','Ориентироваться на длину разметки между автомобилями независимо от погоды','Держаться ближе при плотном потоке, чтобы другие не перестраивались перед вами'],c:1,r:'Безопасная дистанция зависит от скорости, покрытия, видимости, реакции и возможного торможения впереди.',e:'Дистанция — не одно универсальное число метров, а запас для конкретной динамики ситуации.',m:'Воспринимаете дистанцию как фиксированное расстояние'},
{t:'special',s:'lane',q:'Позади приближается специальный автомобиль с включёнными специальными световыми и звуковыми сигналами. Какой общий принцип должен определять ваши действия?',a:['Немедленно остановиться в своей полосе независимо от обстановки','Безопасно и предсказуемо создать условия для его беспрепятственного проезда','Увеличить скорость, чтобы не задерживать специальный автомобиль','Продолжить движение до ближайшего перекрёстка, где уступить проще'],c:1,r:'Предоставление преимущества специальному транспорту должно выполняться так, чтобы не создать новую опасную ситуацию.',e:'Экзаменационный смысл — не в максимально резком освобождении дороги, а в безопасном предоставлении пути.',m:'Выбираете резкое действие вместо безопасного предоставления проезда'},
{t:'special',s:'lane',q:'Специальный автомобиль приближается сзади, но немедленное перестроение вправо заставит вас опасно вклиниться перед другим автомобилем. Что делать?',a:['Всё равно выполнить перестроение: специальный автомобиль всегда имеет абсолютный приоритет','Резко затормозить в своей полосе, чтобы специальный автомобиль объехал','Действовать предсказуемо и освободить путь при первой безопасной возможности','Ускориться до появления свободного промежутка справа'],c:2,r:'Требование предоставить путь не означает обязанность совершать опасный манёвр.',e:'Здесь проверяется способность одновременно учитывать преимущество специального транспорта и безопасность собственного перестроения.',m:'Выполняете требование без учёта безопасности манёвра'},
{t:'special',s:'lane',q:'Можно ли считать любой включённый проблесковый маячок одинаковым основанием для предоставления автомобилю преимущества?',a:['Да, сам факт включённого маячка означает одинаковое преимущество','Нет, значение зависит от вида специального сигнала и предусмотренных правил его применения','Да, если маячок виден одновременно со звуковым сигналом другого автомобиля','Преимущество зависит только от цвета кузова и опознавательных обозначений'],c:1,r:'Специальные световые сигналы имеют разное назначение и не должны автоматически восприниматься одинаково.',e:'Вопрос проверяет понимание системы специальных сигналов, а не реакцию на сам факт мигающего света.',m:'Обобщаете значение специальных сигналов'},
{t:'wording',s:'none',q:'В вопросе спрашивается: «Обязан ли водитель…». Какой способ чтения уменьшает вероятность ошибки?',a:['Выбрать наиболее безопасно звучащий вариант, даже если он описывает рекомендацию','Отделить обязательное требование от действий, которые лишь разрешены или рекомендуются','Сначала исключить самый длинный вариант как чрезмерно конкретный','Сопоставить вопрос только с похожими билетами, которые вы уже решали'],c:1,r:'Слова «обязан», «может», «разрешается» и «запрещается» задают разные юридические условия ответа.',e:'Человек может знать само правило и всё равно ошибиться, если заменит «обязан» на «может».',m:'Не различаете обязательное и допустимое действие'},
{t:'wording',s:'none',q:'Два варианта ответа отличаются только уточнением «только при…». Как лучше проверить, какой из них верный?',a:['Предпочесть вариант без ограничения как более общий','Сопоставить дополнительное условие с точной формулировкой дорожной ситуации и правила','Выбрать вариант, в котором перечислено больше мер безопасности','Ориентироваться на то, какой вариант чаще встречался в тренировках'],c:1,r:'Небольшое дополнительное условие может полностью изменить юридическую корректность ответа.',e:'Сильные экзаменационные вопросы часто отличаются одной оговоркой, а не очевидно абсурдным вариантом.',m:'Пропускаете юридически значимые уточнения'},
{t:'wording',s:'none',q:'Почему после ошибки полезнее объяснить правило своими словами, чем запомнить номер правильного ответа?',a:['Потому что пересказ помогает проверить принцип и перенести его на изменённую ситуацию','Потому что после пересказа можно не возвращаться к тексту ПДД','Потому что собственная формулировка всегда точнее нормативной','Потому что одинаковые вопросы никогда не повторяются на экзамене'],c:0,r:'Понимание принципа позволяет решать новые варианты задачи, тогда как механическое запоминание ответа привязано к конкретной формулировке.',e:'Цель обучения — узнать правило в изменившихся условиях, а не только воспроизвести знакомую букву.',m:'Запоминаете ответ вместо принципа'},
{t:'wording',s:'none',q:'В условии одновременно указаны знак, направление движения и дополнительное ограничение. Какой порядок анализа наиболее устойчив?',a:['Сначала выбрать знакомое правило по ключевому слову, затем проверить остальные детали','Сначала определить все факты условия, затем применить правила по их приоритету и проверить итог на конфликт траекторий','Сначала исключить варианты, которые звучат менее безопасно','Начать с последнего предложения, потому что в нём обычно находится главное условие'],c:1,r:'Сложный вопрос нужно разложить на факты, правила и последствия, а не угадывать по одному знакомому признаку.',e:'Такой алгоритм снижает ошибки на задачах, где одновременно действуют несколько условий.',m:'Решаете вопрос по одному знакомому признаку'}
]

const KB=[
{keys:['помех','справа','равнознач'],topic:'priority',title:'Помеха справа',text:'Правило справа нельзя применять автоматически. Сначала проверь регулирование, знаки приоритета и равнозначность дорог. Только когда более конкретные средства не задают очередность, оцени положение участника справа.'},
{keys:['светофор','зелён','желт','регулиров'],topic:'signals',title:'Светофор и регулирование',text:'Разрешающий сигнал позволяет движение, но не отменяет конфликтующие обязанности: пешеходов, встречные траектории при повороте и невозможность блокировать перекрёсток. При регулировщике сначала учитываются его сигналы.'},
{keys:['перестро','полос','поворотник','маневр'],topic:'manoeuvres',title:'Перестроение',text:'Указатель поворота предупреждает о намерении, но не создаёт преимущества. Перед боковым перемещением оцени соседнюю полосу, слепую зону и скорость сближения.'},
{keys:['пешеход','переход'],topic:'pedestrians',title:'Пешеходы',text:'При поворотах и ограниченной обзорности оцени не только текущее положение пешехода, но и развитие ситуации. Главный вопрос — пересекаются ли ваши траектории и есть ли запас для безопасной реакции.'},
{keys:['скорост','дистанц','дожд','видим','тормоз'],topic:'speed',title:'Скорость и дистанция',text:'Ограничение скорости задаёт верхний предел. Реальная безопасная скорость и дистанция зависят от видимости, покрытия, времени реакции и возможности остановиться в контролируемом пространстве.'},
{keys:['останов','стоян','парков'],topic:'stopping',title:'Остановка и стоянка',text:'Свободное место и наличие других припаркованных автомобилей не доказывают разрешённость. Сначала проверь ограничения, затем обзорность и влияние автомобиля на других участников.'},
{keys:['знак','размет','навигатор'],topic:'signs',title:'Знаки и разметка',text:'Не решай задачу по одному объекту. Учитывай действующие знаки, разметку, сигналы и фактическую дорожную обстановку совместно. Навигатор не заменяет требования дороги.'},
{keys:['спец','маяч','сирен'],topic:'special',title:'Специальный транспорт',text:'Специальные сигналы имеют разное назначение. Если требуется предоставить путь, делай это предсказуемо и безопасно, не создавая опасного резкого манёвра.'}
];

const KEY='pdd_ai_v2_state';
const DEFAULT={version:22,onboard:false,cat:'B',goal:14,explain:'simple',dailyGoal:10,answered:0,correct:0,streak:0,lastDay:'',todayCount:0,todayDate:'',topics:{},mistakes:[],bookmarks:[],history:[],reviews:[],chat:[],agentMemory:{topic:null,intent:null,lastQuestion:null,awaitingCheck:false}};
function loadState(){try{const x=JSON.parse(localStorage.getItem(KEY)||'{}');return {...DEFAULT,...x,topics:x.topics||{},mistakes:x.mistakes||[],bookmarks:x.bookmarks||[],history:x.history||[],reviews:x.reviews||[],chat:x.chat||[],agentMemory:{...DEFAULT.agentMemory,...(x.agentMemory||{})}}}catch(e){return {...DEFAULT,agentMemory:{...DEFAULT.agentMemory}}}}
let S=loadState(),session=null,timer=null,lastAnswer=null,lastResult=null,topicFilter='all',bodyScrollY=0;
const $=id=>document.getElementById(id);

function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}}
function toast(t){const el=$('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function stat(t){if(!S.topics[t])S.topics[t]={n:0,c:0,w:0};return S.topics[t]}
function score(t){const x=stat(t);return x.n?Math.max(5,Math.round(x.c/x.n*100)):50}
function accuracy(){return S.answered?Math.round(S.correct/S.answered*100):0}
function readiness(){const a=Object.keys(TOPICS).map(score),avg=a.reduce((x,y)=>x+y,0)/a.length,vol=Math.min(1,S.answered/100);return Math.min(99,Math.round(avg*.74+vol*25))}
function weakTopic(){return Object.keys(TOPICS).sort((a,b)=>score(a)-score(b))[0]}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function formatTime(s){s=Math.max(0,Math.round(s||0));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function masterIndex(q){return Q.indexOf(q)}
function resetToday(){const d=new Date().toISOString().slice(0,10);if(S.todayDate!==d){S.todayDate=d;S.todayCount=0;save()}}function markActivity(){const d=new Date().toISOString().slice(0,10);if(S.lastDay===d)return;const p=new Date(Date.now()-86400000).toISOString().slice(0,10);S.streak=S.lastDay===p?S.streak+1:1;S.lastDay=d;save()}
function dueReviews(){const now=Date.now();return S.reviews.filter(x=>x.due<=now).sort((a,b)=>a.due-b.due)}
function scheduleReview(idx,wrong=true){let r=S.reviews.find(x=>x.idx===idx);if(!r){r={idx,level:0,due:Date.now()};S.reviews.push(r)}if(wrong){r.level=0;r.due=Date.now()+10*60*1000}else{r.level=Math.min(4,(r.level||0)+1);const gaps=[10*60*1000,864e5,3*864e5,7*864e5,14*864e5];r.due=Date.now()+gaps[r.level]}save()}

function lockBodyScroll(){if(document.body.classList.contains('scroll-locked'))return;bodyScrollY=window.scrollY||window.pageYOffset||0;document.body.style.top='-'+bodyScrollY+'px';document.body.classList.add('scroll-locked')}
function unlockBodyScroll(){if(!document.body.classList.contains('scroll-locked'))return;document.body.classList.remove('scroll-locked');document.body.style.top='';window.scrollTo(0,bodyScrollY||0)}
function init(){resetToday();if(!S.onboard)$('onboard').classList.add('active');if(!S.chat.length){S.chat=[{role:'agent',text:'Привет. Я AI‑агент ПДД. Могу объяснить правило простыми словами, разобрать последнюю ошибку или подобрать тренировку по твоему слабому месту.'}];save()}render()}
function finishOnboard(){S.cat=$('onCat').value;S.goal=+$('onGoal').value;S.onboard=true;save();$('onboard').classList.remove('active');render()}
function showPage(id){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');document.querySelectorAll('.bottom-nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===id));render();scrollTo(0,0)}
function render(){const r=readiness(),w=weakTopic(),a=accuracy();$('homePct').textContent=r+'%';$('homeRing').style.background='conic-gradient(var(--green) '+r*3.6+'deg,#153149 0)';$('continueTopic').textContent='Тема: '+TOPICS[w].name;$('continueMeta').textContent=Math.min(S.todayCount,S.dailyGoal)+' из '+S.dailyGoal;$('statAnswered').textContent=S.answered;$('statAccuracy').textContent=a+'%';$('statStreak').textContent=S.streak;$('statErrors').textContent=S.mistakes.length;$('topicsCat').textContent=S.cat;$('profileCat').value=S.cat;$('explainMode').value=S.explain;$('dailyGoal').value=String(S.dailyGoal);$('categoryStrip').innerHTML=['B','A','C','D'].map(c=>'<button class="category '+(S.cat===c?'active':'')+'" onclick="setCategory(\''+c+'\')"><b>'+c+'</b><small>'+({B:'Легковые',A:'Мото',C:'Грузовые',D:'Автобусы'}[c])+'</small></button>').join('');renderDue();renderTopics();renderAnalytics();renderAgent()}
function renderDue(){const d=dueReviews();$('dueTitle').textContent=d.length?d.length+' вопрос'+(d.length===1?'':'а')+' ждут повторения':'Сегодня всё повторено';$('dueText').textContent=d.length?'Вернись к ошибкам, пока правило не закрепилось.':'Ошибки будут возвращаться через интервалы, чтобы знания не забывались.';$('dueBtn').disabled=!d.length}
function setCategory(v){S.cat=v;save();render();toast('Категория '+v+' выбрана')}
function setExplainMode(v){S.explain=v;save();toast('Режим объяснений сохранён')}
function setDailyGoal(v){S.dailyGoal=+v;save();render();toast('Дневная цель обновлена')}
function setTopicFilter(v,btn){topicFilter=v;document.querySelectorAll('.segmented button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');renderTopics()}
function renderTopics(){let keys=Object.keys(TOPICS);if(topicFilter==='weak')keys=keys.filter(k=>stat(k).n&&score(k)<75);if(topicFilter==='new')keys=keys.filter(k=>!stat(k).n);$('topicList').innerHTML=keys.length?keys.map(k=>{const x=stat(k),s=score(k),v=TOPICS[k];return '<button class="surface topic-item" onclick="startTopic(\''+k+'\')"><div class="topic-line"><div><b>'+v.icon+' '+v.name+'</b><br><small>'+x.n+' решено • '+x.w+' ошибок</small></div><strong>'+s+'%</strong></div><div class="bar"><i style="width:'+s+'%"></i></div></button>'}).join(''):'<div class="surface topic-item"><small>Здесь пока пусто.</small></div>'}
function renderAnalytics(){const r=readiness();$('analyticsPct').textContent=r+'%';$('analyticsRing').style.background='conic-gradient(var(--green) '+r*3.6+'deg,#153149 0)';$('metricAnswered').textContent=S.answered;$('metricCorrect').textContent=S.correct;$('metricExams').textContent=S.history.length;const keys=Object.keys(TOPICS).sort((a,b)=>score(a)-score(b)).slice(0,5);$('weakList').innerHTML=keys.map((k,i)=>{const s=score(k),color=i<2?'#ff6268':i<4?'#ff9f43':'#38e09d';return '<div class="weak-row"><span>'+TOPICS[k].icon+' '+TOPICS[k].name+'</span><div class="weakbar"><i style="width:'+s+'%;background:'+color+'"></i></div><b style="color:'+color+'">'+s+'%</b></div>'}).join('');$('examHistory').innerHTML=S.history.length?S.history.slice().reverse().slice(0,8).map(h=>'<div class="surface history"><div><b class="'+(h.pass?'c-green':'c-red')+'">'+(h.pass?'Сдан':'Не сдан')+'</b><br><small>'+new Date(h.date).toLocaleString('ru-RU')+'</small></div><div><b>'+h.errors+' ош.</b><br><small>'+formatTime(h.sec)+'</small></div></div>').join(''):'<div class="surface history"><small>Попыток пока нет.</small></div>'}

function pick(pool,n){const out=[];shuffle(pool).forEach(q=>{if(!out.includes(q))out.push(q)});return out.slice(0,Math.min(n,out.length))}
function startPractice(){startSession('practice',pick(Q,12))}
function startSmart(){const w=weakTopic();startSession('smart',pick(Q.filter(q=>q.t===w).concat(Q.filter(q=>q.t!==w)),10))}
function startWeak(){const ids=[...new Set(S.mistakes.slice().reverse().map(x=>x.idx))];let p=ids.map(i=>Q[i]).filter(Boolean);if(p.length<8)p=p.concat(Q.filter(q=>q.t===weakTopic()));startSession('weak',pick(p,10))}
function startSaved(){const p=S.bookmarks.map(i=>Q[i]).filter(Boolean);if(!p.length)return toast('В избранном пока нет вопросов');startSession('saved',pick(p,10))}
function startDue(){const p=dueReviews().map(r=>Q[r.idx]).filter(Boolean);if(!p.length)return toast('Повторений пока нет');startSession('review',p.slice(0,10))}
function startTopic(t){startSession('topic',pick(Q.filter(q=>q.t===t),10))}
function startExam(){startSession('exam',pick(Q,10))}
function startSession(mode,questions){if(!questions.length)return toast('Для этого режима пока нет вопросов');session={mode,questions,index:0,answers:new Array(questions.length).fill(null),errors:0,correct:0,start:Date.now(),deadline:mode==='exam'?Date.now()+900000:null,finished:false};lockBodyScroll();$('questionScreen').classList.add('active');if(mode==='exam'){clearInterval(timer);timer=setInterval(tickExam,500)}renderQuestion()}
function tickExam(){if(!session||session.mode!=='exam')return;const left=Math.ceil((session.deadline-Date.now())/1000);if(left<=0){finishExam('time');return}renderMeta()}
function renderMeta(){const total=session.questions.length;$('questionCounter').textContent='Вопрос '+(session.index+1)+' из '+total;if(session.mode==='exam')$('questionTimer').textContent=formatTime(Math.ceil((session.deadline-Date.now())/1000));else $('questionTimer').textContent=({practice:'Тренировка',smart:'Научи меня',weak:'Слабые',saved:'Избранное',review:'Повторение',topic:'Обучение'}[session.mode]||'Практика')}
function sceneLabel(s){return {yield:'Перекрёсток и приоритет',city:'Городской перекрёсток',residential:'Жилая улица',pedestrian:'Пешеходный переход',lane:'Динамика дорожного движения',rain:'Дождь и ограниченная видимость',signal:'Светофор и регулирование',stopping:'Остановка и стоянка',special:'Специальный транспорт',none:'Текстовый вопрос'}[s]||'Дорожная ситуация'}
function imageKeyFor(q){
 if(q.s==='signal')return'lane';
 if(q.s==='stopping')return'yield';
 if(q.s==='special')return'lane';
 return q.s
}
function sceneVariant(q){
 const i=Math.max(0,masterIndex(q));
 const variants={
  yield:[
   {p:'50% 50%',z:'cover',o:'sign'},
   {p:'58% 50%',z:'108% auto',o:'junction'},
   {p:'42% 50%',z:'106% auto',o:'priority'},
   {p:'52% 44%',z:'104% auto',o:'paths'}
  ],
  lane:[
   {p:'50% 50%',z:'cover',o:'lanes'},
   {p:'40% 50%',z:'107% auto',o:'mirror'},
   {p:'60% 50%',z:'106% auto',o:'gap'},
   {p:'50% 42%',z:'104% auto',o:'merge'}
  ],
  pedestrian:[
   {p:'50% 50%',z:'cover',o:'crosswalk'},
   {p:'58% 50%',z:'108% auto',o:'hidden'},
   {p:'43% 50%',z:'106% auto',o:'ped'},
   {p:'50% 44%',z:'104% auto',o:'conflict'}
  ],
  rain:[
   {p:'50% 50%',z:'cover',o:'rain'},
   {p:'47% 46%',z:'107% auto',o:'distance'},
   {p:'56% 50%',z:'105% auto',o:'visibility'},
   {p:'44% 50%',z:'104% auto',o:'braking'}
  ]
 };
 const k=imageKeyFor(q),arr=variants[k]||[{p:'center',z:'cover',o:''}];
 return arr[i%arr.length]
}
function sceneOverlay(type,analysis){
 let x='';
 if(type==='mirror')x='<span class="visual-marker vm-left">слепая зона</span>';
 else if(type==='gap')x='<span class="visual-arrow va-right">→</span><span class="visual-marker vm-left">скорость сближения</span>';
 else if(type==='merge')x='<span class="visual-arrow va-right">↗</span>';
 else if(type==='crosswalk'||type==='ped')x='<span class="visual-zone vz-cross"></span>';
 else if(type==='hidden')x='<span class="visual-marker vm-right">закрытая зона обзора</span>';
 else if(type==='conflict')x='<span class="visual-zone vz-cross"></span><span class="visual-arrow va-center">↘</span>';
 else if(type==='rain'||type==='visibility')x='<span class="visual-marker vm-bottom">видимость • сцепление</span>';
 else if(type==='distance')x='<span class="visual-arrow va-center">↕</span><span class="visual-marker vm-left">запас дистанции</span>';
 else if(type==='braking')x='<span class="visual-marker vm-bottom">путь реакции + торможение</span>';
 else if(type==='sign'||type==='priority')x='<span class="visual-zone vz-sign"></span>';
 else if(type==='junction'||type==='paths')x='<span class="visual-arrow va-center">↔</span>';
 else if(type==='lanes')x='<span class="visual-arrow va-right">↗</span>';
 if(analysis&&lastAnswer){
   x+='<span class="scene-analysis-tag '+(lastAnswer.correct?'good':'bad')+'">'+(lastAnswer.correct?'✓ принцип применён верно':'× здесь была ошибка')+'</span>';
   x+='<span class="scene-tip">'+escapeHtml(lastAnswer.q.r)+'</span>';
 }
 return x
}
function applyScene(el,q,analysis=false){
 const k=imageKeyFor(q),img=(window.SCENE_IMAGES||{})[k],sv=sceneVariant(q);
 el.classList.remove('zoomed');el.classList.toggle('has-photo',!!img);
 el.style.backgroundImage=img?'linear-gradient(180deg,rgba(0,0,0,.01),rgba(0,0,0,.22)),url('+img+')':'';
 el.style.backgroundPosition=sv.p;el.style.backgroundSize=sv.z;
 el.innerHTML='<span class="scene-label">'+sceneLabel(q.s)+'</span>'+sceneOverlay(sv.o,analysis);
 el.style.display=q.s==='none'?'none':'block'
}
function toggleSceneZoom(el){if(!el||el.style.display==='none')return;el.classList.toggle('zoomed')}
function renderQuestion(){const q=session.questions[session.index],ans=session.answers[session.index],exam=session.mode==='exam';renderMeta();$('questionTopic').textContent=TOPICS[q.t].name;const mi=masterIndex(q);$('bookmark').textContent=S.bookmarks.includes(mi)?'♥':'♡';applyScene($('scene'),q,false);$('questionText').textContent=q.q;$('answers').innerHTML=q.a.map((a,i)=>{let cls='answer',mark='';if(ans!==null&&!exam){if(i===q.c){cls+=' correct';mark='✓'}else if(i===ans){cls+=' wrong';mark='×'}}return '<button class="'+cls+'" '+(ans!==null?'disabled':'')+' onclick="answerQuestion('+i+')"><span class="letter">'+String.fromCharCode(65+i)+'</span><span>'+a+'</span><span>'+mark+'</span></button>'}).join('');$('prevQuestion').disabled=session.index===0||exam;$('nextQuestion').disabled=ans===null;$('nextQuestion').textContent=session.index===session.questions.length-1?'Завершить':'Далее ›'}
function answerQuestion(i){if(session.answers[session.index]!==null)return;const q=session.questions[session.index],mi=masterIndex(q),ok=i===q.c,st=stat(q.t);session.answers[session.index]=i;markActivity();S.answered++;S.todayCount++;st.n++;if(ok){S.correct++;session.correct++;st.c++;if(session.mode==='review')scheduleReview(mi,false)}else{session.errors++;st.w++;S.mistakes.push({idx:mi,topic:q.t,m:q.m,choice:i,correct:q.c,date:new Date().toISOString()});if(S.mistakes.length>200)S.mistakes=S.mistakes.slice(-200);scheduleReview(mi,true)}save();lastAnswer={q,choice:i,correct:ok,idx:mi};if(session.mode==='exam'){if(!ok&&session.errors>=2){finishExam('second');return}if(session.index===session.questions.length-1){finishExam('complete');return}session.index++;renderQuestion();return}renderQuestion();setTimeout(openExplanation,120)}
function previousQuestion(){if(session&&session.index>0){session.index--;renderQuestion()}}
function nextQuestion(){if(!session)return;if(session.answers[session.index]===null)return toast('Сначала выбери ответ');if(session.index===session.questions.length-1){session.mode==='exam'?finishExam('complete'):finishTraining();return}session.index++;renderQuestion()}
function attemptCloseQuestion(){if(session&&session.mode==='exam'&&session.answers.some(x=>x!==null)){if(!confirm('Завершить экзамен досрочно? Попытка будет сохранена как незавершённая.'))return;finishExam('abandoned');return}closeQuestion()}
function closeQuestion(){clearInterval(timer);$('questionScreen').classList.remove('active');session=null;unlockBodyScroll();render()}
function toggleBookmark(){if(!session)return;const idx=masterIndex(session.questions[session.index]),p=S.bookmarks.indexOf(idx);if(p>=0)S.bookmarks.splice(p,1);else S.bookmarks.push(idx);save();renderQuestion();toast(p>=0?'Удалено из избранного':'Добавлено в избранное')}

function openExplanation(){const x=lastAnswer;if(!x)return;$('questionScreen').classList.remove('active');$('explainScreen').classList.add('active');$('answerVerdict').className='verdict'+(x.correct?'':' bad');$('answerVerdict').innerHTML='<b class="'+(x.correct?'c-green':'c-red')+'">'+(x.correct?'✓ Правильный ответ':'× Ошибка')+'</b><br>'+String.fromCharCode(65+x.q.c)+'. '+x.q.a[x.q.c];let text=x.q.e;if(!x.correct)text+='<br><br><b>Почему выбранный вариант не подходит:</b> '+wrongReason(x.q,x.choice);if(S.explain==='brief')text=x.q.e;if(S.explain==='deep')text+='<br><br><b>Алгоритм:</b> выдели факты → определи главное правило → проверь конфликт траекторий → оцени безопасность.';$('explanationText').innerHTML=text;applyScene($('explainScene'),x.q,true);$('explainSceneHint').style.display=x.q.s==='none'?'none':'block';$('ruleBox').innerHTML='<b>Ключевой принцип</b><br>'+x.q.r;$('miniAIReply').textContent=''}
function wrongReason(q,c){return c===q.c?'Выбран правильный вариант.':'Вариант «'+q.a[c]+'» не учитывает главное условие. Типичная ошибка: '+q.m+'.'}
function closeExplanation(){$('explainScreen').classList.remove('active');$('questionScreen').classList.add('active')}
function continueAfterExplanation(){$('explainScreen').classList.remove('active');$('questionScreen').classList.add('active');if(session.index===session.questions.length-1)finishTraining();else{session.index++;renderQuestion()}}
function miniAI(type){if(!lastAnswer)return;const q=lastAnswer.q;let t='';if(type==='simple')t='Решай в порядке: что регулирует ситуацию → кто имеет приоритет → пересекаются ли траектории → безопасно ли действие. Здесь главное: '+q.r;if(type==='why')t=wrongReason(q,lastAnswer.choice);if(type==='remember')t='Запомни не букву ответа, а триггер ошибки: '+q.m+'. При следующем похожем вопросе сначала проверь именно это.';if(type==='similar')t='Я добавлю похожую ситуацию в повторение. В ней изменится одно условие, чтобы проверить понимание, а не память.';$('miniAIReply').textContent=t}

function finishTraining(){const answered=session.answers.filter(x=>x!==null).length;lastResult={pass:true,title:'Тренировка завершена',subtitle:'Правильно '+session.correct+' из '+answered+'. Следующая адаптивная сессия учтёт эти ответы.',errors:session.errors,answered,sec:Math.round((Date.now()-session.start)/1000),wrong:session.answers.map((x,i)=>x!==null&&x!==session.questions[i].c?masterIndex(session.questions[i]):null).filter(x=>x!==null)};clearInterval(timer);$('questionScreen').classList.remove('active');showResult();session=null;render()}
function finishExam(reason){if(!session||session.finished)return;session.finished=true;clearInterval(timer);const answered=session.answers.filter(x=>x!==null).length,left=Math.max(0,Math.ceil((session.deadline-Date.now())/1000)),sec=900-left,pass=reason==='complete'&&answered===10&&session.errors<=1;const rec={date:new Date().toISOString(),pass,errors:session.errors,answered,sec,reason};S.history.push(rec);if(S.history.length>50)S.history=S.history.slice(-50);save();lastResult={pass,title:pass?'Экзамен сдан':'Экзамен не сдан',subtitle:pass?'Допущено не более одной ошибки. Отличная попытка.':reason==='second'?'Вторая ошибка — экзамен автоматически завершён.':reason==='time'?'Время истекло.':reason==='abandoned'?'Попытка завершена досрочно.':'Попытка завершена.',errors:session.errors,answered,sec,wrong:session.answers.map((x,i)=>x!==null&&x!==session.questions[i].c?masterIndex(session.questions[i]):null).filter(x=>x!==null)};$('questionScreen').classList.remove('active');showResult();session=null;render()}
function showResult(){const r=lastResult;$('resultIcon').textContent=r.pass?'✓':'×';$('resultIcon').className='result-icon'+(r.pass?'':' fail');$('resultTitle').textContent=r.title;$('resultSubtitle').textContent=r.subtitle;$('resultMetrics').innerHTML='<div class="surface"><b>'+r.answered+'</b><small>ответов</small></div><div class="surface"><b>'+r.errors+'</b><small>ошибок</small></div><div class="surface"><b>'+formatTime(r.sec)+'</b><small>время</small></div>';$('resultReview').innerHTML=r.wrong.length?'<div class="surface result-review"><b>Что повторить:</b><br>'+[...new Set(r.wrong.map(i=>TOPICS[Q[i].t].name))].join(' • ')+'</div>':'<div class="surface result-review"><b class="c-green">Ошибок нет.</b> Закрепи результат на новых формулировках.</div>';$('resultReviewBtn').style.display=r.wrong.length?'block':'none';$('resultScreen').classList.add('active')}
function closeResult(){$('resultScreen').classList.remove('active');unlockBodyScroll();showPage('home')}
function reviewLastResult(){if(!lastResult||!lastResult.wrong.length)return;const p=[...new Set(lastResult.wrong)].map(i=>Q[i]);$('resultScreen').classList.remove('active');startSession('review',p)}
function resetProgress(){if(confirm('Удалить локальный прогресс, историю и чат?')){localStorage.removeItem(KEY);location.reload()}}

function renderAgent(){
 const w=weakTopic(),due=dueReviews().length;
 $('agentFocus').textContent='Слабее всего: '+TOPICS[w].name+' — '+score(w)+'%';
 $('agentFocusText').textContent=due?'Есть '+due+' вопрос(а) для интервального повторения. Агент учитывает их в рекомендациях.':'Агент учитывает категорию '+S.cat+', историю ошибок и текущую готовность '+readiness()+'%.';
 $('chat').innerHTML=S.chat.slice(-40).map(m=>{
   const actions=(m.actions||[]).map(a=>'<button onclick="agentAction(\''+a.cmd+'\',\''+(a.arg||'')+'\')">'+escapeHtml(a.label)+'</button>').join('');
   const meta=m.meta?'<span class="msg-meta">'+escapeHtml(m.meta)+'</span>':'';
   return '<div class="msg '+m.role+'">'+escapeHtml(m.text)+(actions?'<div class="actions">'+actions+'</div>':'')+meta+'</div>';
 }).join('');
 setTimeout(()=>{const c=$('chat');c.scrollTop=c.scrollHeight},0)
}
function escapeHtml(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function askPreset(t){$('agentInput').value=t;sendAgent()}
function agentKey(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendAgent()}}
function normalize(s){return String(s||'').toLowerCase().replace(/ё/g,'е').replace(/[^а-яa-z0-9\s-]/g,' ').replace(/\s+/g,' ').trim()}
function tokens(s){return normalize(s).split(' ').filter(w=>w.length>2)}
const TOPIC_ALIASES={
 priority:['перекрест','приоритет','главн','уступ','помех','равнознач','круг'],
 signals:['светофор','регулировщик','сигнал','зелен','желт','красн'],
 signs:['знак','размет','полос','навигатор','временн'],
 pedestrians:['пешеход','переход','велосипед','самокат'],
 manoeuvres:['перестро','маневр','поворот','разворот','обгон','слеп'],
 stopping:['останов','стоян','парков'],
 speed:['скорост','дистанц','тормоз','дожд','видим','скольз'],
 special:['спец','маяч','сирен','скорая','пожарн'],
 wording:['обязан','может','разреш','запрещ','формулиров','ответ']
};
function detectTopic(text){
 const n=normalize(text);let best=null,bestScore=0;
 for(const [topic,arr] of Object.entries(TOPIC_ALIASES)){let s=0;arr.forEach(k=>{if(n.includes(k))s+=3});if(S.agentMemory.topic===topic&&/^(а|но|почему|тогда|если|а если|что если)/.test(n))s+=2;if(s>bestScore){bestScore=s;best=topic}}
 return bestScore?best:null
}
function detectIntent(text){
 const n=normalize(text);
 if(/последн.*ошиб|ошиб.*последн/.test(n))return'last_error';
 if(/диагност|мои ошиб|слаб.*мест|что.*не понимаю|где.*плох/.test(n))return'diagnose';
 if(/план|подготов|готов.*экзам|сколько.*уч/.test(n))return'plan';
 if(/задай.*вопрос|проверь меня|контрольн.*вопрос|мини.*тест/.test(n))return'quiz';
 if(/проверь.*объяс|я правильно понял|правильно ли я/.test(n))return'check';
 if(/объясн|что значит|как работает|почему/.test(n))return'explain';
 if(/кто.*перв|кто.*уступ|можно ли|должен ли|имеет.*право|ситуац/.test(n))return'scenario';
 if(/повтори|повторение/.test(n))return'review';
 if(/экзамен/.test(n))return'exam';
 return'general'
}
function scenarioMissing(text,topic){
 const n=normalize(text),miss=[];
 if(topic==='priority'||topic==='signals'){
   if(!/(светофор|регулировщик|нерегулиру|знак|главн|уступ|равнознач)/.test(n))miss.push('чем регулируется перекрёсток или какие стоят знаки');
   if(!/(прям|налево|направо|разворот|траектор)/.test(n))miss.push('направления движения участников');
 }
 if(topic==='manoeuvres'&&!/(сосед|полос|сзади|вперед|скорост|слеп)/.test(n))miss.push('положение и движение автомобиля в соседней полосе');
 if(topic==='pedestrians'&&!/(переход|поворач|край|обзор|траектор)/.test(n))miss.push('где находится пешеход и куда движется автомобиль');
 return miss
}
function findKnowledge(text,topic){
 const n=normalize(text),ts=tokens(n);let ranked=[];
 KB.forEach(k=>{let s=k.topic===topic?4:0;k.keys.forEach(x=>{if(n.includes(x))s+=4});ts.forEach(w=>{if(normalize(k.title+' '+k.text).includes(w))s++});ranked.push({k,s})});
 const qrank=Q.map((x,i)=>{let s=x.t===topic?3:0;const blob=normalize(x.q+' '+x.e+' '+x.r+' '+x.m);ts.forEach(w=>{if(blob.includes(w))s+=1});return{x,i,s}}).sort((a,b)=>b.s-a.s);
 ranked.sort((a,b)=>b.s-a.s);
 return{kb:ranked[0]&&ranked[0].s>0?ranked[0]:null,q:qrank[0]&&qrank[0].s>1?qrank[0]:null}
}
function diagnoseAgent(){
 const topicRows=Object.keys(TOPICS).filter(k=>stat(k).n).sort((a,b)=>score(a)-score(b)).slice(0,3);
 const reasons={};S.mistakes.forEach(m=>reasons[m.m]=(reasons[m.m]||0)+1);
 const topReason=Object.entries(reasons).sort((a,b)=>b[1]-a[1])[0];
 if(!S.answered)return{text:'Мне пока мало данных для диагностики. Реши хотя бы 10–15 вопросов: после этого я смогу отличить случайные ошибки от устойчивой слабой темы.',actions:[{label:'Начать диагностику',cmd:'practice'}],meta:'Данных: 0 ответов'};
 const parts=topicRows.map(k=>TOPICS[k].name+' '+score(k)+'%');
 let text='По твоим результатам слабее всего: '+(parts.join(', ')||TOPICS[weakTopic()].name)+'.';
 if(topReason)text+=' Самый частый тип ошибки: «'+topReason[0]+'» ('+topReason[1]+' раз).';
 text+=' Я бы не шёл сразу в полный экзамен: сначала закрой слабую тему, затем интервальное повторение и только потом контрольную попытку.';
 return{text,topic:topicRows[0]||weakTopic(),actions:[{label:'Тренировать слабую тему',cmd:'topic',arg:topicRows[0]||weakTopic()},{label:'Повторить ошибки',cmd:'review'}],meta:'Основано на '+S.answered+' ответах и '+S.mistakes.length+' ошибках'}
}
function planAgent(){
 const r=readiness(),w=weakTopic(),due=dueReviews().length;
 let phase=r<55?'сначала восстановить базовые правила':r<75?'сфокусироваться на слабых темах и стабильности':'переходить к экзаменационной устойчивости';
 const text='Готовность сейчас около '+r+'%. План: 1) '+phase+'; 2) ежедневно '+S.dailyGoal+' вопросов; 3) первая тема — «'+TOPICS[w].name+'» ('+score(w)+'%); 4) '+(due?'закрыть '+due+' отложенных повторений':'пройти короткое интервальное повторение после новых ошибок')+'; 5) сдавать экзамен только после короткой разминки без повторных ошибок.';
 return{text,topic:w,actions:[{label:'Начать план',cmd:'topic',arg:w},{label:'Экзамен',cmd:'exam'}],meta:'Категория '+S.cat+' • готовность '+r+'%'}
}
function lastErrorAgent(){
 const m=S.mistakes.at(-1);if(!m)return{text:'Сохранённых ошибок пока нет. Реши несколько заданий, и я смогу разобрать конкретный неверный выбор.',actions:[{label:'Начать тренировку',cmd:'practice'}]};
 const q=Q[m.idx];let text='Последняя ошибка — «'+TOPICS[q.t].name+'». '+q.e+' Ключевой принцип: '+q.r;
 if(Number.isInteger(m.choice)&&m.choice!==q.c)text+=' Ты выбрал «'+q.a[m.choice]+'», но этот вариант '+wrongReason(q,m.choice).replace(/^Вариант «.*?» /,'');
 text+=' Тип ошибки: '+q.m+'.';
 return{text,topic:q.t,actions:[{label:'Похожая тренировка',cmd:'topic',arg:q.t},{label:'Повторить ошибку',cmd:'review'}],meta:'Разбор последней сохранённой ошибки'}
}
function quizAgent(topic){
 const t=topic||weakTopic(),pool=Q.filter(x=>x.t===t),q=pool[Math.floor(Math.random()*pool.length)];
 S.agentMemory.topic=t;S.agentMemory.lastQuestion=masterIndex(q);S.agentMemory.intent='quiz';save();
 return{text:'Контрольный вопрос по теме «'+TOPICS[t].name+'»: '+q.q+'\n\nA. '+q.a[0]+'\nB. '+q.a[1]+'\nC. '+q.a[2]+'\nD. '+q.a[3]+'\n\nОтветь буквой или своими словами — я проверю логику.',topic:t,meta:'Контроль понимания • без подсказки'}
}
function evaluateQuizAnswer(text){
 const idx=S.agentMemory.lastQuestion,q=Q[idx];if(!q)return null;
 const n=normalize(text);let choice=null;
 const letter=n.match(/^(a|b|c|d|а|б|в|г)(\s|$)/);
 if(letter){const map={a:0,b:1,c:2,d:3,'а':0,'б':1,'в':2,'г':3};choice=map[letter[1]]}
 if(choice===null){q.a.forEach((a,i)=>{const kws=tokens(a).filter(w=>w.length>4);if(kws.some(w=>n.includes(w)))choice=i})}
 S.agentMemory.lastQuestion=null;save();
 if(choice===q.c)return{text:'Верно. Но важнее причина: '+q.r+' Если можешь объяснить это без формулировки ответа, правило действительно усвоено.',topic:q.t,actions:[{label:'Ещё вопрос',cmd:'agentquiz',arg:q.t}],meta:'Проверка: правильный ответ'};
 if(choice!==null)return{text:'Не совсем. Правильный вариант — '+String.fromCharCode(65+q.c)+'. '+q.a[q.c]+'. '+q.e+' Типичная ловушка: '+q.m+'.',topic:q.t,actions:[{label:'Тренировать тему',cmd:'topic',arg:q.t},{label:'Ещё вопрос',cmd:'agentquiz',arg:q.t}],meta:'Проверка: есть пробел в логике'};
 return{text:'Я не смог однозначно определить выбранный вариант. Напиши букву A/B/C/D или сформулируй решение одной фразой.',topic:q.t,meta:'Нужен конкретный ответ'}
}
async function sendAgent(){
 const input=$('agentInput'),q=input.value.trim();if(!q)return;input.value='';
 S.chat.push({role:'user',text:q});renderAgent();
 const pending={role:'agent',text:'Анализирую условие…',meta:'Проверяю контекст и твою статистику'};S.chat.push(pending);renderAgent();
 await new Promise(r=>setTimeout(r,120));
 S.chat.pop();
 const answer=await agentAnswer(q);
 S.chat.push({role:'agent',...answer});
 if(S.chat.length>80)S.chat=S.chat.slice(-80);save();renderAgent()
}
async function agentAnswer(text){
 const n=normalize(text);
 if(S.agentMemory.lastQuestion!==null){const checked=evaluateQuizAnswer(text);if(checked)return checked}
 const intent=detectIntent(text),topic=detectTopic(text)||S.agentMemory.topic||null;
 S.agentMemory.intent=intent;if(topic)S.agentMemory.topic=topic;save();
 if(intent==='last_error')return lastErrorAgent();
 if(intent==='diagnose')return diagnoseAgent();
 if(intent==='plan')return planAgent();
 if(intent==='quiz')return quizAgent(topic);
 if(intent==='review')return{text:'У тебя сейчас '+dueReviews().length+' вопрос(а) готовы к интервальному повторению. Начни с них: задача — ответить правильно не по памяти, а объясняя себе правило.',actions:[{label:'Начать повторение',cmd:'review'}],meta:'Интервальное повторение'};
 if(intent==='exam')return{text:'Экзамен в приложении: 10 вопросов, 15 минут, вторая ошибка завершает попытку. Перед ним я рекомендую сначала закрыть текущие повторения и слабую тему «'+TOPICS[weakTopic()].name+'».',actions:[{label:'Начать экзамен',cmd:'exam'}],meta:'Текущий режим приложения'};
 if(intent==='check'){S.agentMemory.awaitingCheck=true;save();return{text:'Напиши правило своими словами так, как объяснил бы его другому ученику. Я проверю, есть ли в объяснении главный принцип и не перепутан ли приоритет.',topic:topic||weakTopic(),meta:'Режим проверки понимания'}}
 if(S.agentMemory.awaitingCheck){
   const t=topic||S.agentMemory.topic||weakTopic(),info=findKnowledge(text,t),base=info.kb?info.kb.k.text:(info.q?info.q.x.r:'');
   S.agentMemory.awaitingCheck=false;save();
   const overlap=tokens(base).filter(w=>tokens(text).includes(w)).length;
   return{text:overlap>=2?'Суть ты передал правильно. Я бы добавил одну вещь: '+base:'В объяснении есть часть идеи, но не хватает ключевого условия. Ориентир: '+base,topic:t,actions:[{label:'Проверить на вопросе',cmd:'agentquiz',arg:t}],meta:'Проверка понимания, а не запоминания'};
 }
 if(intent==='scenario'&&topic){const missing=scenarioMissing(text,topic);if(missing.length)return{text:'Чтобы ответить точно, мне не хватает условия: '+missing.join('; ')+'. Добавь это — и я разберу очередность по шагам.',topic,meta:'Не додумываю отсутствующие условия'}}
 const info=findKnowledge(text,topic);
 if(info.kb){
   const k=info.kb.k;let textOut=k.title+': '+k.text;
   if(intent==='scenario')textOut+=' Алгоритм для конкретной ситуации: сначала зафиксируй регулирование и знаки, затем направления движения, после этого проверь конфликт траекторий.';
   return{text:textOut,topic:k.topic,actions:[{label:'Тренировать тему',cmd:'topic',arg:k.topic},{label:'Контрольный вопрос',cmd:'agentquiz',arg:k.topic}],meta:'Встроенная база знаний • '+TOPICS[k.topic].name};
 }
 if(info.q){const x=info.q.x;return{text:'Ближе всего вопрос относится к теме «'+TOPICS[x.t].name+'». '+x.r+' '+x.e,topic:x.t,actions:[{label:'Тренировать тему',cmd:'topic',arg:x.t}],meta:'Подобрано по базе учебных ситуаций'}}
 return{text:'Я не хочу придумывать правило без достаточного основания. Опиши ситуацию конкретнее: какие знаки или сигнал действуют, кто откуда едет и какой манёвр выполняет. Тогда я разберу её по шагам.',topic:topic||null,meta:'Низкая уверенность — требуется уточнение'}
}
function agentAction(cmd,arg){
 if(cmd==='topic')return startTopic(arg);
 if(cmd==='review')return startDue();
 if(cmd==='exam')return startExam();
 if(cmd==='practice')return startPractice();
 if(cmd==='agentquiz'){const a=quizAgent(arg);S.chat.push({role:'agent',...a});save();renderAgent();return}
}
init();